-- Baseline schema (the tables as they were when the festival started).
-- Do not edit this file to change the schema. CREATE TABLE IF NOT EXISTS skips a table
-- that already exists, so a changed table here reaches new databases (and the tests) but
-- never a database that is already in use. Add a numbered file to app/migrations/ instead.
-- See docs/adr/0002-schema-changes-are-numbered-migrations.md and docs/runbook.md.

CREATE TABLE IF NOT EXISTS events (
    id        INTEGER PRIMARY KEY,
    title     TEXT    NOT NULL,
    venue     TEXT    NOT NULL,
    starts_at TEXT    NOT NULL,          -- ISO 8601, festival local time
    capacity  INTEGER NOT NULL CHECK (capacity > 0)
);

CREATE TABLE IF NOT EXISTS reservations (
    id         INTEGER PRIMARY KEY,
    event_id   INTEGER NOT NULL REFERENCES events(id),
    attendee   TEXT    NOT NULL,
    created_at TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
